+            }
+            if (operationQueue.isEmpty()) {
+                return null;
+            }
+            var op = operationQueue.pollFirst();
+            if (op.seqNo() == lastSeenSeqNo) {
+                skippedOperations++;
+                continue;
+            }
+            lastSeenSeqNo = op.seqNo();
+            return op;
+        }
+    }
